import{_ as o,o as e,c as l,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Ceph DocuBetter Meeting 2019-01-18","description":"","frontmatter":{"title":"Ceph DocuBetter Meeting 2019-01-18","date":"2019-01-18T00:00:00.000Z","updated":"2019-02-03T00:00:00.000Z","tags":["Ceph 文档优化","SEO 改进","文档生成自动化","项目实习生","Ceph 文档团队"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/Ceph_DocuBetter_Meeting_2019-01-18.md","filePath":"posts/2019/Ceph_DocuBetter_Meeting_2019-01-18.md","lastUpdated":1780460162000}'),i={name:"posts/2019/Ceph_DocuBetter_Meeting_2019-01-18.md"};function n(s,t,a,p,c,g){return e(),l("div",null,[...t[0]||(t[0]=[r('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2019-01-18</p><p><strong>参会人员</strong>： Ceph 文档团队成员、SEO 专家、项目实习生等</p><p><strong>会议主题</strong>： Ceph 文档优化与 SEO 改进</p><p><strong>会议内容</strong>：</p><p><strong>1. 文档结构优化</strong>：</p><ul><li><strong>问题</strong>： Ceph 文档覆盖多个版本，可能导致用户误入旧版本文档。</li><li><strong>解决方案</strong>： <ul><li>使用 <code>rel canonical</code> 标签指向主版本作为标准版本。</li><li>使用别名（如 <code>/current</code>）指向最新稳定版本。</li><li>自动化文档生成过程，包括生成 <code>rel canonical</code> 标签和 <code>robots.txt</code> 文件。</li></ul></li></ul><p><strong>2. SEO 改进</strong>：</p><ul><li><strong>问题</strong>： 搜索引擎索引了过时的文档版本，导致用户体验不佳。</li><li><strong>解决方案</strong>： <ul><li>在 <code>robots.txt</code> 文件中排除旧版本文档。</li><li>考虑使用白名单而非黑名单，以便搜索引擎仍能索引最新版本。</li></ul></li></ul><p><strong>3. 文档生成自动化</strong>：</p><ul><li><strong>问题</strong>： 文档生成过程依赖人工干预，效率低下。</li><li><strong>解决方案</strong>： <ul><li>将文档生成过程集成到 Jenkins 作业中，实现自动化。</li><li>利用可读性文件自动创建链接和 <code>rel canonical</code> 标签。</li></ul></li></ul><p><strong>4. 项目实习生</strong>：</p><ul><li><strong>问题</strong>： 需要额外的资源来优化文档和 SEO。</li><li><strong>解决方案</strong>： <ul><li>招聘实习生，负责文档编写和生成工作。</li><li>实习生参与每周会议，了解项目进展。</li></ul></li></ul><p><strong>5. 其他</strong>：</p><ul><li><strong>JavaScript backboards</strong>： 已合并 luminous 和 mimic 版本的 backboards，jewel 版本的 backboards 尚未完成。</li></ul><p><strong>行动计划</strong>：</p><ul><li>Ceph 文档团队与 SEO 专家合作，制定详细的文档优化和 SEO 改进计划。</li><li>评估 Jenkins 作业，实现文档生成自动化。</li><li>与 David Galloway 合作，优化 <code>robots.txt</code> 文件。</li><li>招聘实习生，负责文档编写和生成工作。</li></ul><p><strong>备注</strong>：</p><ul><li>会议中提到的部分关键词：SEO、rel canonical、robots.txt、Jenkins、Sphinx、白名单、黑名单、实习生、Ceph 文档团队。</li></ul>',19)])])}const _=o(i,[["render",n]]);export{d as __pageData,_ as default};
